using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using Prometheus;
class Tests024 {
 static List<string> passed=new List<string>();static void Check(bool condition,string label){if(!condition)throw new Exception("FAIL "+label);passed.Add(label);Console.WriteLine("PASS "+label);}
 static void Reject(Action action,string label){try{action();}catch{passed.Add(label);Console.WriteLine("PASS rejected "+label);return;}throw new Exception("Invalid action accepted: "+label);}
 static void Main(string[] args){string root=Path.GetFullPath(args[0]);Tools.Root=Path.GetFullPath(args[1]);var token=CancellationToken.None;
  var e=new Editor();var media=Media.Inspect(Path.Combine(root,"source.mp4"),token);var voice=Media.Inspect(Path.Combine(root,"voice.wav"),token);Check(media.streams.Count==2&&media.sha256.Length==64,"MP4 H264/AAC inspected and hashed");Check(voice.streams[0].codec=="pcm_s24le"&&voice.streams[0].sample_rate==44100,"WAV PCM24 mono44.1k inspected");
  e.Commit(p=>{p.assets.Add(media);p.assets.Add(voice);Media.Insert(p,media.id,p.Active.tracks.First(t=>t.kind=="video").id,0);});Check(e.Project.Active.clips.Count==2&&e.Project.Active.link_groups.Count==1,"linked import");var video=e.Project.Active.clips.First(c=>e.Project.Active.tracks.Find(t=>t.id==c.track_id).kind=="video");string videoId=video.id;double original=video.duration.Seconds;
  e.Cut(videoId,1);Check(e.Project.Active.clips.Count==4&&e.Project.Active.link_groups.Count==2,"linked cut creates two groups");var right=e.Project.Active.clips.Where(c=>e.Project.Active.tracks.Find(t=>t.id==c.track_id).kind=="video").OrderBy(c=>c.timeline_start.Seconds).Last();Check(right.source_in.Seconds==1&&Math.Abs(right.duration.Seconds-(original-1))<0.000001,"source-time continuity");
  string before=Store.Encode(e.Project);e.Move(right.id,0,null);Check(e.Project.Active.clips.Count==2,"move overwrites occupied linked destination");e.Undo();Check(Store.Encode(e.Project)==before,"overwrite undo restores complete snapshot");e.Move(right.id,2,null);Check(e.Project.Active.clips.Count(c=>c.timeline_start.Seconds==2)==2,"linked move preserves delta");e.Undo();Check(Store.Encode(e.Project)==before,"undo restores complete snapshot");e.Redo();Check(e.Project.Active.clips.Count(c=>c.timeline_start.Seconds==2)==2,"redo restores linked move");
  e.Unlink(right.id);Check(e.Project.Active.link_groups.Count==1,"unlink keeps media");e.Commit(p=>{var c=p.Active.clips.Find(x=>x.id==right.id);p.Active.tracks.Find(t=>t.id==c.track_id).locked=true;});Reject(()=>e.Delete(right.id),"locked track mutation");e.Undo();
  string file=Path.Combine(root,"roundtrip.prometheus.json");Store.Save(e.Project,file);var reopened=Store.Load(file);Check(Store.Encode(reopened)==Store.Encode(e.Project),"save/reopen preserves project contract");Store.Save(e.Project,file);Check(File.Exists(file+".bak"),"atomic replace keeps previous project");
  Reject(()=>{var p=Store.Copy(e.Project);p.Active.clips[0].duration=Rational.Time(100);Store.Validate(p);},"source overflow");Reject(()=>{var p=Store.Copy(e.Project);p.Active.clips[0].asset_id="missing";Store.Validate(p);},"broken reference");Reject(()=>{var p=Store.Copy(e.Project);p.schema_version="future";Store.Validate(p);},"future schema");
  e.Commit(p=>Media.Insert(p,voice.id,p.Active.tracks.Where(t=>t.kind=="audio").OrderBy(t=>t.order).Last().id,0));using(var bitmap=Rendering.Frame(e.Project,0.5,token)){Check(bitmap.Width==640&&bitmap.Height==360,"composited preview frame");bitmap.Save(Path.Combine(root,"frame.png"));}
  string mp4=Path.Combine(root,"export.mp4"),wav=Path.Combine(root,"export.wav");Rendering.Export(e.Project,mp4,token);Rendering.Export(e.Project,wav,token);var exported=Media.Inspect(mp4,token);Check(exported.streams.First(s=>s.kind=="video").nominal_fps.Seconds==60,"export CFR60 H264/AAC");var audio=Media.Inspect(wav,token);Check(audio.streams[0].sample_rate==48000&&audio.streams[0].channels==2,"audio mix PCM16 stereo48k");Check(Math.Abs(exported.streams.First(s=>s.kind=="video").duration.Seconds-e.Project.Active.Length)<1.0/60+0.001,"export duration matches montage");
  int frames=0;Rendering.Play(e.Project,0,Path.Combine(root,"temp"),token,(b,t)=>{frames++;b.Dispose();},s=>{});Check(frames>5,"streaming preview with prepared audio completes");
  var offset=Media.Inspect(Path.Combine(root,"offset.mp4"),token);var linked=new Editor();linked.Commit(p=>{p.assets.Add(offset);Media.Insert(p,offset.id,p.Active.tracks.First(t=>t.kind=="video").id,0);});var audioClip=linked.Project.Active.clips.First(c=>linked.Project.Active.tracks.Find(t=>t.id==c.track_id).kind=="audio");double offsetTime=offset.streams.First(s=>s.kind=="audio").pts_origin.Seconds-offset.presentation_origin.Seconds;Check(Math.Abs(audioClip.timeline_start.Seconds-offsetTime)<1.0/48000,"nonzero audio offset preserved to sample precision");var linkedVideo=linked.Project.Active.clips.First(c=>linked.Project.Active.tracks.Find(t=>t.id==c.track_id).kind=="video");linked.Cut(linkedVideo.id,0.25);Check(linked.Project.Active.link_groups.Count==1&&linked.Project.Active.link_groups[0].clip_ids.Contains(audioClip.id)&&linked.Project.Active.clips.First(c=>c.id==linked.Project.Active.link_groups[0].clip_ids.First(id=>id!=audioClip.id)).timeline_start.Seconds==0.25,"cut before delayed audio keeps correct right-hand linkage");
  Rendering.Export(linked.Project,Path.Combine(root,"offset-export.wav"),token);
  var cancellation=new CancellationTokenSource();cancellation.Cancel();byte[] oldOutput=File.ReadAllBytes(wav);Reject(()=>Rendering.Export(e.Project,wav,cancellation.Token),"cancelled export");Check(File.ReadAllBytes(wav).SequenceEqual(oldOutput),"cancelled export preserves prior output");Check(Directory.GetFiles(root,"*.partial-*").Length==0,"cancelled export cleans partial files");
  string changedFile=Path.Combine(root,"changed.wav");File.Copy(Path.Combine(root,"voice.wav"),changedFile,true);var changed=Media.Inspect(changedFile,token);Media.Verify(changed,token);using(var f=new FileStream(changedFile,FileMode.Append))f.WriteByte(0);Reject(()=>Media.Verify(changed,token),"changed source identity");
  string encoded=Store.Encode(e.Project);Reject(()=>Store.Decode(encoded.Substring(0,encoded.Length-1)+",\"unknown\":true}"),"unknown project field");
  Store.Json();File.WriteAllText(Path.Combine(root,"checks-engine024.json"),Store.Json().Serialize(new{status="PASS",checks=passed}));
 }
}
